func atBreak(which int32) int32 {
	// The asset Model with one thing wrong (by `which`); what `model-check-assets` says. 0 broken: well formed. `which` 5
	// does not break it but adds a byte, and answers 1 when `model-hash-assets` sees the byte (else 0).
	var nodes *port.Cells = port.NewCells()
	var attrs *port.Cells = port.NewCells()
	var regions *port.Cells = port.NewCells()
	var text *port.Cells = port.NewCells()
	var pages *port.Cells = port.NewCells()
	var ledger *port.Cells = port.NewCells()
	var layout *port.Cells = port.NewCells()
	var assets *port.Cells = port.NewCells()
	var uses *port.Cells = port.NewCells()
	var st *port.Cells = port.NewCells()
	var tmp *port.Cells = port.NewCells()
	var abytes *port.Buf = port.NewBuf()
	var h0 int64 = int64(0)
	atBuild(nodes, attrs, regions, text, pages, ledger, layout, assets, uses, abytes, st, tmp)
	if which == 1 {
		port.CellsSet(assets, 29, port.CellsAt(assets, 29)+1)
	}
	if which == 2 {
		port.CellsSet(uses, 1, 9999)
	}
	if which == 3 {
		model.NodeSetAttrInt(nodes, attrs, 7, model.FkAsset(), 5)
	}
	if which == 4 {
		model.NodeSetAttrInt(nodes, attrs, 1, model.FkNoasset(), 2)
	}
	if which == 5 {
		h0 = model.ModelHashAssets(int64(0), assets, uses, abytes)
		port.BufPush(abytes, 7)
		if model.ModelHashAssets(int64(0), assets, uses, abytes) != h0 {
			return 1
		}
		return 0
	}
	return model.ModelCheckAssets(nodes, attrs, assets, uses, abytes, st)
}

