func atGeo(res *port.Cells, sigs int32) int32 {
	// Nine figures and seals that are not provisional figures, placed against three candidates; their outcomes into `res`.
	var nodes *port.Cells = port.NewCells()
	var attrs *port.Cells = port.NewCells()
	var regions *port.Cells = port.NewCells()
	var text *port.Cells = port.NewCells()
	var pages *port.Cells = port.NewCells()
	var ledger *port.Cells = port.NewCells()
	var layout *port.Cells = port.NewCells()
	var assets *port.Cells = port.NewCells()
	var uses *port.Cells = port.NewCells()
	var cand *port.Cells = port.NewCells()
	var box *port.Cells = port.NewCells()
	var cbytes *port.Buf = port.NewBuf()
	var abytes *port.Buf = port.NewBuf()
	model.ModelInit(nodes, attrs, regions, text, pages, ledger, layout)
	atBytes(cbytes, 4, 97)
	atBytes(cbytes, 4, 98)
	// C0 and C1 are images, C2 a page-sized one (its pixels are not made: part)
	atCand(cand, 1, 10000, 10000, 30000, 30000, 0, 0, 4, 1)
	atCand(cand, 1, 50000, 10000, 70000, 30000, 0, 4, 4, 2)
	atCand(cand, 1, 100000, 100000, 120000, 120000, 2, 0, 0, 0)
	atFigAt(nodes, regions, model.NkFigure(), model.FgUnknown(), 1, 10000, 10000, 30000, 30000)
	atFigAt(nodes, regions, model.NkFigure(), model.FgUnknown(), 1, 12000, 12000, 20000, 20000)
	atFigAt(nodes, regions, model.NkFigure(), model.FgUnknown(), 1, 20000, 10000, 60000, 30000)
	atFigAt(nodes, regions, model.NkFigure(), model.FgUnknown(), 1, 200000, 200000, 220000, 220000)
	atFigAt(nodes, regions, model.NkSeal(), model.SlSignature(), 1, 10000, 10000, 30000, 30000)
	atFigAt(nodes, regions, model.NkSeal(), model.SlDigitalSignature(), 1, 10000, 10000, 30000, 30000)
	atFigAt(nodes, regions, model.NkSeal(), model.SlStamp(), 1, 50000, 10000, 70000, 30000)
	atFigAt(nodes, regions, model.NkFigure(), model.FgUnknown(), 1, 100000, 100000, 120000, 120000)
	atFigAt(nodes, regions, model.NkFigure(), model.FgUnknown(), -1, 0, 0, 0, 0)
	atBox(box)
	asset.AsRun(nodes, attrs, regions, cand, cbytes, assets, uses, abytes, 8, 100, sigs, box)
	port.CellsDrop(res, 0)
	var n int32 = 1
	for n <= 9 {
		port.CellsPush(res, model.NodeAttrIntOr(nodes, attrs, n, model.FkAsset(), -1))
		port.CellsPush(res, model.NodeAttrIntOr(nodes, attrs, n, model.FkNoasset(), -1))
		n += 1
	}
	return 0
}

func TestANodeIsTheImageItIsOrSaysWhyNot(emonT *testing.T) {
	var res *port.Cells = port.NewCells()
	atGeo(res, 0)
	port.AssertEq(emonT, port.CellsAt(res, 0), 0, "a figure that is one whole image gets it (asset 0)")
	port.AssertEq(emonT, port.CellsAt(res, 3), model.NzPart(), "a figure inside one image's box is part of it")
	port.AssertEq(emonT, port.CellsAt(res, 5), model.NzComposite(), "a figure over two images is a composite")
	port.AssertEq(emonT, port.CellsAt(res, 7), model.NzVector(), "a figure with no image under it is vector")
	port.AssertEq(emonT, port.CellsAt(res, 9), model.NzWithheld(), "a signature seal is withheld")
	port.AssertEq(emonT, port.CellsAt(res, 10), -1, "a digital signature has no pixels and no field")
	port.AssertEq(emonT, port.CellsAt(res, 11), -1, "no reason either")
	port.AssertEq(emonT, port.CellsAt(res, 12), 1, "a stamp seal that is one image gets it (asset 1)")
	port.AssertEq(emonT, port.CellsAt(res, 15), model.NzPart(), "an image the size of a page is never an asset at images")
	port.AssertEq(emonT, port.CellsAt(res, 17), model.NzVector(), "a node with no region is vector")
	// with asset-signatures on, the signature seal is the image
	atGeo(res, 1)
	port.AssertEq(emonT, port.CellsAt(res, 8), 0, "a signature seal gets the image when signatures are on")
	port.AssertEq(emonT, port.CellsAt(res, 9), -1, "and has no reason")
}

